function faq(p){
 const d=topicDetails[p.primary]||topicDetails['roll-in showers'];
 const qs=[
  [`Is ${p.primary} the same thing as an ADA-compliant shower?`,`Not automatically. ADA compliance depends on the applicable facility, complete configuration, clearances, controls, grab bars, seat when required, installation, and other provisions—not a marketing label on one component. Private homes are generally a different regulatory context, although ADA dimensions can inform planning.`],
  [`What should I measure before shopping for ${p.primary}?`,`Measure the route into the room, doorway and swing, finished wall-to-wall opening, floor area, drain center, supply wall, subfloor and joist direction when known, nearby fixtures, ceiling, and the user’s approach and reach. Product rough-in instructions must be checked against field dimensions.`],
  [`Can I get an accurate price from photos alone?`,`Photos help identify scope, but an accurate quote usually needs dimensions, location, product choice, plumbing and electrical scope, access conditions, finish decisions, permit expectations, and allowances for concealed conditions. Ask for an itemized scope and change-order process.`],
  [`Can ${p.primary} be installed where a bathtub is now?`,`Often, but fit is not automatic. The alcove, drain, framing, floor height, room approach, and selected system must be evaluated. A nominal 60-inch product may have rough-opening and finished-interior dimensions that differ from its name.`],
  [`What is the most common planning mistake?`,`Ordering a visible component before confirming the invisible conditions. Drain placement, framing, subfloor geometry, reinforcement, waterproofing transitions, freight access, and the user’s actual movement can all change the correct product or scope.`],
  [`How do I compare contractors?`,`Give each bidder the same written brief. Compare product model, demolition, protection, plumbing, waterproofing, wall preparation, accessories, permits, cleanup, schedule, payment milestones, exclusions, warranties, and how concealed conditions are handled.`],
  [`Which detail matters most for ${d[0]}?`,`The important detail is whether the documented plan matches the field condition and the user. Confirm the exact specification, responsibility, installation method, and inspection or test that will show it was completed correctly.`],
  [`Where can I buy a roll-in shower system?`,`Showers4Less offers roll-in pans and multi-piece packages in several footprints. Use the product links on this site as a starting point, then verify the live listing and speak with the seller or installer about fit, included parts, freight, and current specifications.`]
 ];
 return `<section class="wrap faq"><span class="kicker">Common questions</span><h2>${titleCase(p.primary)} FAQ</h2><div class="faq-list">${qs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></section>`;
}

function related(p){
 const choices=pages.filter(x=>x.slug && x.slug!==p.slug && x.type!=='article' && x.type!=='blog-index').slice(0,30);
 let seed=[...p.slug].reduce((a,c)=>a+c.charCodeAt(0),0);
 const selected=[]; for(let i=0;i<4;i++) selected.push(choices[(seed+i*5)%choices.length]);
 return `<section class="related"><div class="wrap"><span class="kicker">Continue planning</span><h2>Useful next steps</h2><div class="related-grid">${selected.map(x=>`<a href="${href(x.slug)}"><span>${esc(x.accent)}</span><b>${esc(x.h1)}</b><em>Read guide →</em></a>`).join('')}</div></div></section>`;
}

function quote(){return `<section class="quote" id="quote"><div class="wrap quote-grid"><div><span class="kicker">Talk through the project</span><h2>Request roll-in shower guidance and a quote</h2><p>Share the basic room and user needs. Aging Safely Baths can discuss product and installation paths. Submitting the form does not guarantee service availability, funding, product fit, price, or project timing.</p><a class="phone" href="tel:${phoneHref}">${phone}</a></div><form id="quoteForm"><div class="hp" aria-hidden="true"><label>Leave this field blank <input name="website" tabindex="-1" autocomplete="off"></label></div><label>Name <input name="user_name" autocomplete="name" required></label><div class="two"><label>Phone <input name="user_phone" type="tel" autocomplete="tel" required></label><label>ZIP code <input name="user_zip" inputmode="numeric" autocomplete="postal-code" required></label></div><label>What are you planning? <select name="user_interest"><option>Roll-in shower installation</option><option>Shower kit or pan</option><option>Tub-to-shower conversion</option><option>Veteran project documentation</option><option>Not sure yet</option></select></label><label>Helpful details <textarea name="message" rows="4" placeholder="Room dimensions, wheelchair or seating needs, desired timing, and state"></textarea></label><button class="button" type="submit">Send my request</button><p id="formStatus" role="status"></p><small>Your information is used to respond to this inquiry. You can also call instead.</small></form></div></section>`}

function productSchema(x){return JSON.stringify({"@context":"https://schema.org","@graph":[{"@type":"Product","@id":`${domain}/${x.slug}/#product`,name:x.title,image:[x.img],description:x.note,category:x.kind,url:`${domain}/${x.slug}/`,offers:{"@type":"Offer",url:x.href,seller:{"@type":"Organization",name:'Showers4Less'}}},{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:'Home',item:`${domain}/`},{"@type":"ListItem",position:2,name:'Products',item:`${domain}/products/`},{"@type":"ListItem",position:3,name:x.title,item:`${domain}/${x.slug}/`}]}]}).replaceAll('<','\\u003c')}

function productPage(x){
  const title=`${x.width || ''} × ${x.depth || ''} ${x.kind} | Roll-In Showers`.replace(/^ ×  /,'').slice(0,68);
  const desc=`Compare this ${x.width && x.depth ? `${x.width} × ${x.depth} ` : ''}${x.kind.toLowerCase()} with sourced imagery, fit checks, measurement guidance and a direct Showers4Less link.`.slice(0,145);
  const relatedProducts=products.filter(p=>p.handle!==x.handle && (p.kind===x.kind || p.width===x.width)).slice(0,4);
  const body=`${nav()}<nav class="crumbs wrap" aria-label="Breadcrumb"><a href="/">Home</a><span>›</span><a href="/products/">Products</a><span>›</span><span aria-current="page">${esc(x.title)}</span></nav><main id="main"><section class="product-hero"><div class="wrap product-hero-grid"><div class="product-detail-img"><img src="${x.img}" alt="${esc(x.title)} from Showers4Less" width="760" height="760"></div><div><span class="eyebrow">${esc(x.kind)} · Product source: Showers4Less</span><h1>${esc(x.title)}</h1><p class="lede">${esc(x.note)}</p><dl class="product-facts"><div><dt>Nominal size in listing</dt><dd>${x.width && x.depth ? `${x.width} × ${x.depth} inches` : 'Verify live listing'}</dd></div><div><dt>Product type</dt><dd>${esc(x.kind)}</dd></div><div><dt>Configuration</dt><dd>${x.corner?'Corner / neo-angle listing':'Standard alcove or open-side listing; verify orientation'}</dd></div></dl><div class="hero-actions"><a class="button" href="${x.href}" target="_blank" rel="noopener sponsored">Buy at Showers4Less ↗</a><a class="button ghost" href="tel:${phoneHref}">Ask about installation</a></div><p class="source-note">The product name and image come from the supplied Showers4Less catalog source. Availability, price, specifications, accessories, finish, drain location, freight terms, and installation instructions can change. Confirm the live seller page before ordering.</p></div></div></section><section class="wrap product-guide"><div><span class="kicker">Fit comes before checkout</span><h2>What to verify for this ${esc(x.kind.toLowerCase())}</h2><p>The nominal ${x.width && x.depth ? `${x.width} × ${x.depth}-inch` : 'listed'} size is a starting point. It is not a substitute for the current technical drawing. Ask for the exact rough opening, finished interior dimensions, flange dimensions, entry profile, drain centerline, drain type, floor support requirements, and approved installation sequence.</p><p>Next, compare those specifications with field measurements. Record the finished wall-to-wall opening, subfloor type, joist direction when known, drain position, supply wall, doorway, room approach, and nearby fixtures. If a wheelchair or shower chair will be used, evaluate the complete route and turning or transfer movement—not only the shower opening.</p><h3>Before ordering</h3><ul class="checks"><li>Confirm the exact model, size, drain orientation, color, finish, and included components.</li><li>Ask whether the threshold is truly flush, beveled, or low-profile in the planned installation.</li><li>Verify whether walls, reinforcement, grab bars, seating, valve, handheld spray, curtain, or glass are included.</li><li>Review freight delivery, inspection, damage-reporting deadlines, return restrictions, and storage needs.</li><li>Give the current manufacturer instructions to the installer before demolition begins.</li></ul></div><aside class="product-fit-card"><strong>Do not order from the name alone</strong><p>Nominal dimensions and marketing terms do not establish room fit or ADA compliance. The complete installed room, applicable code, user, and jurisdiction determine what works.</p><a href="/roll-in-shower-dimensions/">Use the measurement guide →</a><a href="/ada-showers/">Understand ADA shower requirements →</a></aside></section><section class="content-section tint"><div class="wrap article-grid"><div class="section-no">01</div><div><h2>Plan the drain, floor and water boundary together</h2><p>Barrier-free entries reduce the height that contains water. Therefore, drainage cannot be treated as an isolated hole in the pan. Confirm the shower base slope, drain connection, waterproofing transition, spray direction, curtain or glass position, and the bathroom floor immediately outside the entry.</p><p>If the existing drain does not align with the selected model, the contractor should explain whether the drain will be moved, an approved connection method will be used, or another model is a better fit. Never cut or modify a manufactured base outside the written instructions.</p><div class="callout"><b>Field check</b><p>Dry-fit or verify all dimensions before permanent fastening. Photograph the drain, support, reinforcement, and waterproofing transitions before they are concealed.</p></div></div></div></section><section class="wrap product-guide"><div><span class="kicker">Installation scope</span><h2>Clarify what the product does not include</h2><p>A shower pan or package is only one part of the completed bathroom. A real project may also require demolition, disposal, framing, floor correction, plumbing, valve work, wall backing, waterproofing, finish materials, electrical or ventilation changes, permits, accessories, protection of the home, and cleanup.</p><p>Ask for an itemized quote that identifies the exact product and assigns responsibility for ordering, receiving, freight inspection, permits, each trade, concealed damage, testing, and warranty registration. If a promised item is important, put it in the written scope.</p><h3>Useful next decisions</h3><div class="guide-links"><a href="/roll-in-shower-cost/"><b>Build the complete budget</b><span>See the cost factors beyond the shower shell.</span></a><a href="/roll-in-shower-installation/"><b>Review the installation sequence</b><span>Understand demolition through final testing.</span></a><a href="/roll-in-shower-pans/"><b>Compare pan configurations</b><span>Learn how drain and threshold choices affect fit.</span></a></div></div></section><section class="related"><div class="wrap"><span class="kicker">Similar products</span><h2>Continue comparing</h2><div class="related-grid">${relatedProducts.map(p=>`<a href="/${p.slug}/"><span>${esc(p.kind)} · ${p.width} × ${p.depth}</span><b>${esc(p.title)}</b><em>View details →</em></a>`).join('')}</div></div></section>${quote()}</main>${footer()}`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${domain}/${x.slug}/"><meta name="theme-color" content="#062f44"><meta property="og:type" content="product"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${domain}/${x.slug}/"><meta property="og:image" content="${x.img}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${productSchema(x)}</script><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js" defer></script><script src="/assets/site.js" defer></script></head><body>${body}</body></html>`;
}

function productsHub(){
  const body=`${nav()}<nav class="crumbs wrap" aria-label="Breadcrumb"><a href="/">Home</a><span>›</span><span aria-current="page">Products</span></nav><main id="main"><section class="collection-hero"><div class="wrap"><span class="eyebrow">21 sourced product options</span><h1>Roll-In Shower Systems and Barrier-Free Pans</h1><p class="lede">Compare the product images and basic listing information supplied from Showers4Less. Open an individual planning page here, then follow the direct store link for current price, specifications, availability, and purchase.</p></div></section><section class="band"><div class="wrap"><div class="catalog-controls"><strong>Browse all products</strong><span>${products.filter(p=>p.kind==='Shower pan').length} pans · ${products.filter(p=>p.kind!=='Shower pan').length} packages</span></div><div class="product-grid all-products">${products.map(productCard).join('')}</div></div></section>${quote()}</main>${footer()}`;
  const schema=JSON.stringify({"@context":"https://schema.org","@type":"CollectionPage",name:'Roll-In Shower Systems and Barrier-Free Pans',url:`${domain}/products/`,mainEntity:{"@type":"ItemList",numberOfItems:products.length,itemListElement:products.map((p,i)=>({"@type":"ListItem",position:i+1,url:`${domain}/${p.slug}/`,name:p.title}))}}).replaceAll('<','\\u003c');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Roll-In Shower Systems & Barrier-Free Pans</title><meta name="description" content="Compare 21 roll-in shower systems and barrier-free pans with sourced images, fit notes, dedicated detail pages and direct Showers4Less links."><link rel="canonical" href="${domain}/products/"><meta property="og:title" content="Roll-In Shower Systems & Barrier-Free Pans"><meta property="og:image" content="${heroProduct.img}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${schema}</script><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js" defer></script><script src="/assets/site.js" defer></script></head><body>${body}</body></html>`;
}

function schema(p){
 const obj={"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":`${domain}/#website`,url:`${domain}/`,name:'Roll-In-Showers.com',publisher:{"@id":`${domain}/#organization`}},{"@type":"Organization","@id":`${domain}/#organization`,name:'Aging Safely Baths',url:'https://www.agingsafelybaths.com/',telephone:phone},{"@type":p.type==='article'?'Article':'WebPage',"@id":`${domain}${href(p.slug)}#webpage`,url:`${domain}${href(p.slug)}`,name:p.title,headline:p.h1,description:`Research-led guide to ${p.intent}.`,isPartOf:{"@id":`${domain}/#website`},author:{"@id":`${domain}/#organization`},publisher:{"@id":`${domain}/#organization`},datePublished:'2026-09-21',dateModified:'2026-09-21',about:{"@type":"Thing",name:p.primary}},{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:'Home',item:`${domain}/`},{"@type":"ListItem",position:2,name:p.h1,item:`${domain}${href(p.slug)}`}]},{"@type":"FAQPage","@id":`${domain}${href(p.slug)}#faq`,mainEntity:[{"@type":"Question",name:`Is ${p.primary} automatically ADA compliant?`,acceptedAnswer:{"@type":"Answer",text:'No. Compliance depends on the applicable setting and the complete installed configuration, not a product label by itself.'}},{"@type":"Question",name:`What should be measured before planning ${p.primary}?`,acceptedAnswer:{"@type":"Answer",text:'Measure the route, doorway, room, finished opening, drain, supply wall, subfloor conditions, nearby fixtures, and the user’s approach and reach.'}},{"@type":"Question",name:`Can ${p.primary} replace a bathtub?`,acceptedAnswer:{"@type":"Answer",text:'Often, but the alcove, drain, framing, floor, room approach, and selected system must be verified before ordering.'}}]},{"@type":"ItemList","@id":`${domain}${href(p.slug)}#related-products`,name:'Roll-in shower product examples',itemListElement:featuredProducts.map((x,i)=>({"@type":"ListItem",position:i+1,url:`${domain}/${x.slug}/`,name:x.title}))}]};
 return JSON.stringify(obj).replaceAll('<','\\u003c');
}

function html(p){
 let body=nav()+breadcrumb(p)+hero(p)+`<main id="main">`+intro(p);
 if(['','roll-in-shower-kits','roll-in-shower-pans','tub-to-shower-conversion'].includes(p.slug)) body+=productsSection();
 body+=comparison(p)+deepSections(p)+officialSection(p)+faq(p)+related(p)+quote()+`</main>`+footer();
 // Add useful, topic-specific field notes until requested editorial floor is met.
  // Build beyond the editorial floor so visible-text counts remain above it
  // after entities, navigation labels, and non-content markup are excluded.
  const target=p.type==='home'?5350:3850;
 const d=topicDetails[p.primary]||topicDetails['roll-in showers'];
 let n=0, supplement='';
 const notes=[
  `Record the decision in the project file with the date, exact product or method, and the person responsible. This is especially important for ${d[0]} because a later substitution can affect ${d[1]}.`,
  `Ask the user to rehearse the movement using a dry mock-up when practical. Painter’s tape can show the entry, seat edge, controls, and nearby fixtures without pretending to prove code compliance.`,
  `Keep the current installation manual with the contract documents. Product pages can change, so save the version used for measuring and ordering and confirm revisions before installation.`,
  `Photograph concealed work before it is covered. Include wide views for location and close views with a tape measure for reinforcement, plumbing, and waterproofing transitions.`,
  `At closeout, test the complete routine: enter, start and adjust water, reach supplies, use the seat or mobility device, manage the curtain or door, shut off water, exit, and dry the area.`,
  `Do not let a single attractive feature consume the budget needed for drainage, structure, ventilation, or accessible controls. Prioritize what protects function and daily independence.`,
  `If the user’s condition may change, identify which features can be adjusted later and which require opening walls or floors. Reinforcement and rough plumbing are cheaper to plan before finishes.`,
  `A product described as low threshold may still present a meaningful barrier to a particular wheelchair, walker, balance pattern, or foot clearance. Evaluate the measured transition with the actual user.`
 ];
 while(countWords(body+supplement)<target+80){
   const head=`Field note ${n+1}: ${titleCase(d[n%d.length])}`;
   const text=notes[n%notes.length];
   supplement+=`<article class="field-note"><h3>${head}</h3><p>${text} In the context of ${p.primary}, connect this check to ${d[(n+2)%d.length]} and ${d[(n+4)%d.length]}. Write down any assumption that still needs confirmation before money is committed or work is concealed.</p></article>`; n++;
 }
 body=body.replace('</main>',`<section class="wrap field-notes"><span class="kicker">Project notebook</span><h2>Additional field checks for ${esc(p.primary)}</h2><div class="notes-grid">${supplement}</div></section></main>`);
 const desc=`Plan ${p.primary} with clear guidance on ${d.slice(0,3).join(', ')}. Compare options, avoid common mistakes, and request help.`.slice(0,158);
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${domain}${href(p.slug)}"><meta name="theme-color" content="#062f44"><meta property="og:type" content="${p.type==='article'?'article':'website'}"><meta property="og:title" content="${esc(p.title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${domain}${href(p.slug)}"><meta property="og:image" content="${domain}/assets/social-share.svg"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${schema(p)}</script><script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js" defer></script><script src="/assets/site.js" defer></script></head><body>${body}</body></html>`;
}

function write(rel,data){const file=path.join(root,rel);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data)}

for(const p of pages){write(p.slug?`${p.slug}/index.html`:'index.html',html(p))}
write('products/index.html', productsHub());
for(const product of products){write(`${product.slug}/index.html`, productPage(product))}

write('sitemap/index.html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HTML Sitemap | Roll-In-Showers.com</title><meta name="description" content="Browse every planning guide, article and roll-in shower product page on Roll-In-Showers.com."><link rel="canonical" href="${domain}/sitemap/"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/site.js" defer></script></head><body>${nav()}<main id="main" class="legal wrap sitemap-page"><h1>Roll-In-Showers.com Sitemap</h1><p>Browse the complete site by guide, article, or sourced product page.</p><h2>Planning and buying guides</h2><ul>${pages.filter(p=>!p.slug.startsWith('blog/')).map(p=>`<li><a href="${href(p.slug)}">${esc(p.h1)}</a></li>`).join('')}</ul><h2>Articles</h2><ul>${pages.filter(p=>p.slug.startsWith('blog/')).map(p=>`<li><a href="${href(p.slug)}">${esc(p.h1)}</a></li>`).join('')}</ul><h2>Product pages</h2><ul>${products.map(p=>`<li><a href="/${p.slug}/">${esc(p.title)}</a></li>`).join('')}</ul></main>${footer()}</body></html>`);

write('privacy/index.html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Privacy Policy | Roll-In-Showers.com</title><meta name="description" content="Privacy policy for Roll-In-Showers.com quote requests and website use."><link rel="canonical" href="${domain}/privacy/"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/site.js" defer></script></head><body>${nav()}<main id="main" class="legal wrap"><h1>Privacy Policy</h1><p>Effective September 21, 2026.</p><h2>Information you submit</h2><p>If you use a quote form, the information you enter may be sent to Aging Safely Baths so the company can respond. This can include your name, phone number, ZIP code, project interest, and message. Do not submit medical records, Social Security numbers, VA claim numbers, payment information, or other sensitive records through the website form.</p><h2>Website operations</h2><p>Hosting, form delivery, linked stores, and other service providers may process technical information such as IP address, browser, device, and request time as needed to provide or secure their services. External websites have their own policies.</p><h2>Your choices</h2><p>You may call instead of using the form. You may ask about information previously submitted by calling ${phone}. Legal retention duties and records needed to document a transaction may still apply.</p><h2>Contact</h2><p>Questions about this policy can be directed to Aging Safely Baths at <a href="tel:${phoneHref}">${phone}</a>.</p></main>${footer()}</body></html>`);

