write('assets/site.js',`document.addEventListener('DOMContentLoaded',()=>{const m=document.querySelector('.menu'),n=document.querySelector('#primary-nav');if(m&&n)m.addEventListener('click',()=>{const o=n.classList.toggle('open');m.setAttribute('aria-expanded',String(o))});const io='IntersectionObserver'in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{rootMargin:'0px 0px -8%'}):null;document.querySelectorAll('.product-card,.answer-card,.related-grid a').forEach(el=>{el.classList.add('reveal');if(io)io.observe(el);else el.classList.add('visible')});const f=document.querySelector('#quoteForm'),s=document.querySelector('#formStatus');if(f&&window.emailjs){emailjs.init({publicKey:'alWutsHLG6c3h9P2j'});f.addEventListener('submit',async e=>{e.preventDefault();if(f.elements.website&&f.elements.website.value)return;const b=f.querySelector('button');b.disabled=true;b.textContent='Sending…';s.textContent='Sending your request…';try{await emailjs.sendForm('service_usimtub','template_5n0cskt',f);s.textContent='Request received. A representative will follow up.';f.reset();b.textContent='Request sent'}catch(err){s.textContent='The form could not send. Please call ${phone}.';b.disabled=false;b.textContent='Send my request'}})}});`);

